const (
	automationGraphNodeWidth  = 170.0
	automationGraphNodeHeight = 104.0
	automationGraphPadding    = 60.0
)

func automationBuilderPostURL(page models.AutomationBuilderPage, currentProjectID string) string {
	if page.AutomationID != "" {
		return fmt.Sprintf("/automations/%s/builder?project_id=%s", page.AutomationID, currentProjectID)
	}
	return fmt.Sprintf("/automations/builder?project_id=%s", currentProjectID)
}

func automationDraftCandidateJSON(candidate models.AutomationDraftCandidate) string {
	value, _ := json.Marshal(candidate)
	return string(value)
}
func automationDraftEdgesJSON(edges []models.AutomationDraftEdge) string {
	if edges == nil {
		return "[]"
	}
	value, _ := json.Marshal(edges)
	return string(value)
}
func automationValidationMessages(issues []models.AutomationValidationIssue, _ []models.AutomationDraftNode) []string {
	messages := []string{}
	seen := map[string]bool{}
	for _, issue := range issues {
		if !seen[issue.Message] {
			messages = append(messages, issue.Message)
			seen[issue.Message] = true
		}
	}
	return messages
}
func automationDraftHasConfig(node models.AutomationDraftNode, key string) bool {
	_, ok := node.Config[key]
	return ok
}
func automationDraftSupportsGoal(node models.AutomationDraftNode) bool {
	return node.Type == models.AutomationNodeTrigger || node.Type == models.AutomationNodeAgentTask
}
func automationDraftStringConfig(node models.AutomationDraftNode, key string) string {
	value, _ := node.Config[key].(string)
	return value
}
func automationDraftStringSliceConfig(node models.AutomationDraftNode, key string) string {
	values := []string{}
	switch configured := node.Config[key].(type) {
	case []string:
		values = append(values, configured...)
	case []any:
		for _, value := range configured {
			if text, ok := value.(string); ok {
				values = append(values, text)
			}
		}
	}
	return strings.Join(values, ", ")
}
func automationDraftStringSliceContains(node models.AutomationDraftNode, key, expected string) bool {
	switch values := node.Config[key].(type) {
	case []string:
		for _, value := range values {
			if value == expected {
				return true
			}
		}
	case []any:
		for _, value := range values {
			if text, ok := value.(string); ok && text == expected {
				return true
			}
		}
	}
	return false
}
func automationDraftIntConfig(node models.AutomationDraftNode, key string) int {
	switch value := node.Config[key].(type) {
	case int:
		return value
	case float64:
		return int(value)
	case json.Number:
		parsed, _ := value.Int64()
		return int(parsed)
	}
	return 0
}
func automationDraftBoolConfig(node models.AutomationDraftNode, key string) bool {
	value, _ := node.Config[key].(bool)
	return value
}
func automationDraftHasNode(nodes []models.AutomationDraftNode, key string) bool {
	for _, node := range nodes {
		if node.Key == key {
			return true
		}
	}
	return false
}
func automationDraftNodeName(nodes []models.AutomationDraftNode, key string) string {
	for _, node := range nodes {
		if node.Key == key {
			return node.Name
		}
	}
	return key
}
func automationDraftNodeRole(nodes []models.AutomationDraftNode, key string) string {
	for _, node := range nodes {
		if node.Key == key {
			return node.Role
		}
	}
	return ""
}
func automationDraftEdgeConditionState(edge models.AutomationDraftEdge) string {
	value, _ := edge.Condition["state"].(string)
	return value
}
func automationDraftDefaultX(nodes []models.AutomationDraftNode, key string) float64 {
	for _, node := range nodes {
		if node.Key == key && node.Position != nil {
			return node.Position.X
		}
	}
	return 0
}
func automationDraftDefaultY(nodes []models.AutomationDraftNode, key string) float64 {
	for _, node := range nodes {
		if node.Key == key && node.Position != nil {
			return node.Position.Y
		}
	}
	return 0
}
func automationDraftGraphViewBox(nodes []models.AutomationDraftNode) string {
	var first *models.AutomationDraftPoint
	for _, node := range nodes {
		if node.Position != nil {
			first = node.Position
			break
		}
	}
	if first == nil {
		return "-60 -60 900 540"
	}
	minX, minY, maxX, maxY := first.X, first.Y, first.X+automationGraphNodeWidth, first.Y+automationGraphNodeHeight
	for _, node := range nodes {
		if node.Position == nil {
			continue
		}
		if node.Position.X < minX {
			minX = node.Position.X
		}
		if node.Position.Y < minY {
			minY = node.Position.Y
		}
		if node.Position.X+automationGraphNodeWidth > maxX {
			maxX = node.Position.X + automationGraphNodeWidth
		}
		if node.Position.Y+automationGraphNodeHeight > maxY {
			maxY = node.Position.Y + automationGraphNodeHeight
		}
	}
	return fmt.Sprintf("%.0f %.0f %.0f %.0f", minX-automationGraphPadding, minY-automationGraphPadding, maxX-minX+2*automationGraphPadding, maxY-minY+2*automationGraphPadding)
}
func automationDraftEdgeNodes(nodes []models.AutomationDraftNode, edge models.AutomationDraftEdge) (models.AutomationDraftNode, models.AutomationDraftNode, bool) {
	var source, target models.AutomationDraftNode
	var sourceOK, targetOK bool
	for _, node := range nodes {
		if node.Key == edge.From {
			source, sourceOK = node, node.Position != nil
		}
		if node.Key == edge.To {
			target, targetOK = node, node.Position != nil
		}
	}
	return source, target, sourceOK && targetOK
}
func automationNodeTypeLabel(nodeType models.AutomationNodeType) string {
	if nodeType == models.AutomationNodeTrigger {
		return "Schedule"
	}
	if nodeType == models.AutomationNodeAgentTask {
		return "Task"
	}
	return strings.Title(strings.ReplaceAll(string(nodeType), "_", " "))
}
func automationAdapterLabel(adapterKey string) string {
	return strings.Title(strings.ReplaceAll(adapterKey, "_", " "))
}

func automationCardURL(card models.AutomationCard, currentProjectID string) string {
	return fmt.Sprintf("/automations/%s?project_id=%s", card.Automation.ID, currentProjectID)
}
func automationCardSearchText(card models.AutomationCard) string {
	return strings.Join([]string{card.Automation.Name, card.Automation.Description, card.Version.AdapterKey, string(card.Automation.LifecycleState), string(card.Automation.HealthState)}, " ")
}
func automationLiveNodeTaskURL(node models.AutomationLiveNode, resources []models.AutomationResourceSummary, projectID string, automationID string, automationName string) string {
	if node.NodeType != models.AutomationNodeTrigger && node.NodeType != models.AutomationNodeAgentTask {
		return ""
	}
	for _, resource := range resources {
		if resource.NodeID == node.ID && resource.ResourceType == "task" && resource.ResourceID != "" {
			return fmt.Sprintf("/tasks/%s?project_id=%s&from=automation&automation_id=%s&automation_name=%s", resource.ResourceID, url.QueryEscape(projectID), url.QueryEscape(automationID), url.QueryEscape(automationName))
		}
	}
	return ""
}

